class RegistryMeta(type):
    # Class-level registry shared by every class built with this metaclass.
    registry = {}

    def __init__(cls, name, bases, namespace):
        # Always let type finish building the class first.
        super().__init__(name, bases, namespace)
        # Record THIS class into the shared registry under its name.
        RegistryMeta.registry[name] = cls

# --- demo (do not change) ---
class Dog(metaclass=RegistryMeta):
    pass

class Cat(metaclass=RegistryMeta):
    pass

print(sorted(RegistryMeta.registry))
